// Build the SOP §5 welcome email — branches on onboarder_type.
// Inbound payload (from Next.js fireOnboardingTemplate):
//   { onboarderId, template:'welcome', event, context: {
//     onboarder_type ('contractor'|'intern'), full_name, first_name, personal_email,
//     role_title, onboarding_lead, chief_of_staff, direct_supervisor
//   } }

const body = ($input.first().json.body ?? $input.first().json);
const ctx  = body.context || {};
const type             = ctx.onboarder_type   || 'contractor';
const toEmail          = ctx.personal_email   || body.to;
const firstName        = ctx.first_name       || (ctx.full_name || 'there').split(' ')[0];
const onboardingLead   = ctx.onboarding_lead  || 'Erich';
const chiefOfStaff     = ctx.chief_of_staff   || 'the Chief of Staff';
const directSupervisor = ctx.direct_supervisor|| 'your Direct Supervisor';

if (!toEmail) {
  throw new Error('No personal_email on context — cannot send welcome email');
}

const subject = 'Welcome to the Team — Onboarding Information';

let body_;
if (type === 'intern') {
  body_ = `Hi ${firstName},

We're excited to have you on board. Welcome to the team! Here are your next steps to get started:

1. DOWNLOAD MICROSOFT TEAMS
   Please download the MS Teams app so we can add you to our group chat.

2. ADD US ON TEAMS
   Once installed, kindly add the following contacts:
     • ${chiefOfStaff} — Chief of Staff
     • ${onboardingLead} — Onboarding Lead
     • ${directSupervisor} — Direct Supervisor

3. Send us a quick message once you're connected so we can initiate your onboarding process.

4. COMPLETE THE INTERN ONBOARDING FORM
   We'll share the link with you once you message us on Teams.

Once you've downloaded Teams, we'll move forward with setting up your email account. If you have any questions, feel free to reach out.

Looking forward to working with you!

Best regards,
${onboardingLead}
Onboarding Lead, Romega Solutions`;
} else {
  body_ = `Hi ${firstName},

We're thrilled to have you join the team. Welcome aboard! To kick off your onboarding, here are the next steps:

1. DOWNLOAD MICROSOFT TEAMS
   Please install the Microsoft Teams app (desktop or mobile) so we can add you to our group chat and begin team communications.

2. ADD US ON TEAMS
   Once installed, kindly add the following contacts:
     • ${chiefOfStaff} — Chief of Staff
     • ${onboardingLead} — Onboarding Lead
     • ${directSupervisor} — Direct Supervisor

   Once you've added us, send a quick message so we can begin your onboarding process.

3. FILL OUT THE ONBOARDING FORM
   We'll share the link with you once you message us on Teams.

4. W-8 FORM (FOR COMPLIANCE)
   We'll attach two files when we share the onboarding form: a blank W-8 form and a sample filled form for reference. Please review the sample carefully, fill out the required sections, and upload the completed W-8 through the onboarding form.

If anything is unclear or you need assistance, feel free to reach out. Looking forward to working with you!

Best regards,
${onboardingLead}
Onboarding Lead, Romega Solutions`;
}

return [{ json: { to: toEmail, subject, body: body_, onboarderId: body.onboarderId, template: 'welcome', onboarderType: type } }];

const to = String($json.to || '').trim().toLowerCase();
const payload = ($('Webhook').first().json.body ?? $('Webhook').first().json);
const ccRecipient = String(payload.context?.onboarding_lead_email || payload.context?.requested_by_email || '').trim().toLowerCase();
const cc = ccRecipient && ccRecipient !== to ? ccRecipient : '';

return [{ json: { ...$json, cc } }];
